contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(this).balance;

        // ensure c is funded so that a successful withdrawAll moves a nonzero amount
        c.fallback{value: 1}();

        uint cBalanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        uint cBalanceAfter = address(c).balance;
        uint afterCount = c.depositsCount();

        if (caller == address(this)) {
            // owner path: must not revert and must drain c to zero
            assert(!reverted && cBalanceAfter == 0 && afterCount == beforeCount);
        } else {
            // non-owner path: must revert and leave c's balance untouched
            assert(reverted && cBalanceAfter == cBalanceBefore && afterCount == beforeCount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(address(this).balance >= 1);

        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        // Fund c with 1 wei using a plain value transfer.
        // Since c has no receive()/payable fallback that does not modify depositsCount,
        // the payable fallback increments depositsCount. (Actually the fallback is payable,
        // so it DOES increment depositsCount; see below.)
        (bool ok, ) = address(c).call{value: 1}("");
        require(ok, "funding c failed");

        uint cBalanceFunded = address(c).balance;
        uint depositsFunded = c.depositsCount();

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: as owner (this contract deployed c), withdrawAll must succeed
        // and transfer the entire balance of c to the caller, leaving depositsCount untouched.
        assert(
            !reverted
            && cBalanceAfter == 0
            && selfBalanceAfter == selfBalanceBefore + cBalanceFunded
            && depositsAfter == depositsFunded
        );
    }

    receive() external payable {}
}

