    function run(address target, bytes memory data, uint amount) public payable {
        require(address(this).balance >= amount);
        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        // Build a low-level call to sendMoney that forwards Ether, since the
        // compiler disallows setting {value:} on the non-payable external function.
        (bool reverted, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, amount, data)
        );
        reverted = !reverted;

        if (reverted) {
            assert(address(c).balance == beforeBalance && c.depositsCount() == beforeCount);
        } else {
            assert(address(c).balance == beforeBalance - amount);
        }
    }

    receive() external payable {}
}

