contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();

        uint contractBalanceBefore = address(c).balance;
        uint senderBalanceBefore = address(this).balance;

        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint contractBalanceAfter = address(c).balance;
        uint senderBalanceAfter = address(this).balance;

        bool success = !reverted;
        bool senderGained = senderBalanceAfter == senderBalanceBefore + amount;
        bool contractLost = contractBalanceAfter == contractBalanceBefore - amount;
        bool balancesUnchanged = contractBalanceAfter == contractBalanceBefore && senderBalanceAfter == senderBalanceBefore;

        assert(success == senderGained && success == contractLost && !success == balancesUnchanged);
    }

    receive() external payable {}
}

