contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");

        uint balBefore = address(c).balance;

        // Set up the state the rule needs: fund c with some Ether via fallback.
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk, "deposit to c failed");
        require(address(c).balance == balBefore + amount, "c balance not increased by deposit");

        // Make the deciding call: withdrawAll() as owner. This call must succeed and drain c.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        assert(!reverted && balAfter == 0);
    }

    receive() external payable {}
}

